export function focalPosition(row={}){const clamp=n=>Math.max(0,Math.min(100,Number.isFinite(Number(n))?Number(n):50));return `${clamp(row.focal_x??50)}% ${clamp(row.focal_y??50)}%`;}
export async function fetchPhotoSettings(config){const rows=[];for(let offset=0;;offset+=500){const r=await fetch(config.supabaseUrl+'/rest/v1/elan_photo_settings?select=key,focal_x,focal_y,featured,is_cover&order=key&limit=500&offset='+offset,{headers:{apikey:config.publishableKey},signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('Photo settings are unavailable.');const batch=await r.json();rows.push(...batch);if(batch.length<500)break;}return new Map(rows.map(r=>[r.key,r]));}
export function orderGallery(rows,settings){return rows.map((r,i)=>({r,i})).sort((a,b)=>Number(!!settings.get('gallery-'+b.r.id)?.featured)-Number(!!settings.get('gallery-'+a.r.id)?.featured)||a.i-b.i).map(x=>x.r);}
